<?php defined('ABSPATH')||exit; function bluprint_product_showcase_defaults(){ return [ 'enabled'=>1, 'title'=>'کوچک‌اند، اما کارساز', 'source'=>'recent', 'product_ids'=>'', 'limit'=>8, 'orderby'=>'date', 'order'=>'DESC', 'out_of_stock_text'=>'به‌زودی موجود می‌شود' ]; }
function bluprint_product_showcase_sanitize($value){ $d=bluprint_product_showcase_defaults(); $value=is_array($value)?$value:[]; $source=$value['source']??$d['source']; $orderby=$value['orderby']??$d['orderby']; $order=$value['order']??$d['order']; $allowed_orderby=['date','menu_order','title','price','rand']; $ids=preg_split('/[\s,،]+/',sanitize_text_field($value['product_ids']??''),-1,PREG_SPLIT_NO_EMPTY); $ids=array_values(array_unique(array_filter(array_map('absint',$ids)))); return [ 'enabled'=>!empty($value['enabled'])?1:0, 'title'=>sanitize_text_field($value['title']??$d['title']), 'source'=>in_array($source,['recent','manual','featured'],true)?$source:'recent', 'product_ids'=>implode(',',$ids), 'limit'=>max(1,min(24,absint($value['limit']??$d['limit']))), 'orderby'=>in_array($orderby,$allowed_orderby,true)?$orderby:'date', 'order'=>$order==='ASC'?'ASC':'DESC', 'out_of_stock_text'=>sanitize_text_field($value['out_of_stock_text']??$d['out_of_stock_text']) ]; }
function bluprint_product_showcase_register(){ register_setting('bluprint_product_showcase_group','bluprint_product_showcase',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_product_showcase_sanitize', 'default'=>bluprint_product_showcase_defaults() ]); add_submenu_page('bluprint-settings','محصولات صفحه اصلی','محصولات صفحه اصلی','manage_options','bluprint-product-showcase','bluprint_product_showcase_admin'); }
add_action('admin_menu','bluprint_product_showcase_register'); function bluprint_product_showcase_admin(){ if(!current_user_can('manage_options'))return; $d=wp_parse_args(get_option('bluprint_product_showcase',[]),bluprint_product_showcase_defaults()); ?> <div class="wrap"> <h1>سکشن محصولات صفحه اصلی</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_product_showcase_group'); ?> <table class="form-table"> <tr> <th>وضعیت سکشن</th> <td><label><input type="checkbox" name="bluprint_product_showcase[enabled]" value="1" <?php checked($d['enabled'],1); ?>> نمایش سکشن در صفحه اصلی</label></td> </tr> <tr> <th><label for="bp-product-title">عنوان سکشن</label></th> <td><input id="bp-product-title" class="large-text" name="bluprint_product_showcase[title]" value="<?php echo esc_attr($d['title']); ?>"></td> </tr> <tr> <th><label for="bp-product-source">منبع محصولات</label></th> <td> <select id="bp-product-source" name="bluprint_product_showcase[source]"> <option value="recent" <?php selected($d['source'],'recent'); ?>>جدیدترین محصولات</option> <option value="manual" <?php selected($d['source'],'manual'); ?>>انتخاب دستی محصولات</option> <option value="featured" <?php selected($d['source'],'featured'); ?>>محصولات ویژه</option> </select> </td> </tr> <tr> <th><label for="bp-product-ids">شناسه محصولات</label></th> <td> <textarea id="bp-product-ids" class="large-text" rows="3" name="bluprint_product_showcase[product_ids]"><?php echo esc_textarea($d['product_ids']); ?></textarea> <p class="description">فقط در حالت انتخاب دستی استفاده می‌شود. شناسه‌ها را با کاما جدا کن. ترتیب شناسه‌ها، ترتیب نمایش کارت‌ها را تعیین می‌کند.</p> </td> </tr> <tr> <th><label for="bp-product-orderby">مرتب‌سازی محصولات ویژه</label></th> <td> <select id="bp-product-orderby" name="bluprint_product_showcase[orderby]"> <option value="date" <?php selected($d['orderby'],'date'); ?>>تاریخ انتشار</option> <option value="menu_order" <?php selected($d['orderby'],'menu_order'); ?>>ترتیب منو</option> <option value="title" <?php selected($d['orderby'],'title'); ?>>عنوان</option> <option value="price" <?php selected($d['orderby'],'price'); ?>>قیمت</option> <option value="rand" <?php selected($d['orderby'],'rand'); ?>>تصادفی</option> </select> <select name="bluprint_product_showcase[order]"> <option value="DESC" <?php selected($d['order'],'DESC'); ?>>نزولی</option> <option value="ASC" <?php selected($d['order'],'ASC'); ?>>صعودی</option> </select> <p class="description">این تنظیم فقط برای محصولات ویژه استفاده می‌شود.</p> </td> </tr> <tr> <th><label for="bp-product-limit">تعداد محصولات</label></th> <td><input type="number" id="bp-product-limit" min="1" max="24" name="bluprint_product_showcase[limit]" value="<?php echo esc_attr($d['limit']); ?>"></td> </tr> <tr> <th><label for="bp-out-of-stock-text">متن پیش‌فرض محصولات ناموجود</label></th> <td> <input id="bp-out-of-stock-text" class="large-text" name="bluprint_product_showcase[out_of_stock_text]" value="<?php echo esc_attr($d['out_of_stock_text']); ?>"> <p class="description">اگر محصول ناموجود باشد و متن اختصاصی نداشته باشد، این متن نمایش داده می‌شود. خالی گذاشتن این فیلد، متن «ناموجود» را نمایش می‌دهد.</p> </td> </tr> </table> <?php submit_button('ذخیره تنظیمات'); ?> </form> </div> <?php }
function bluprint_get_product_showcase_data(){ return wp_parse_args(get_option('bluprint_product_showcase',[]),bluprint_product_showcase_defaults()); }
function bluprint_get_product_showcase_products(){ if(!function_exists('wc_get_products'))return []; $d=bluprint_get_product_showcase_data(); $args=[ 'status'=>'publish', 'limit'=>$d['limit'], 'return'=>'objects' ]; if($d['source']==='manual'){ $ids=array_filter(array_map('absint',explode(',',$d['product_ids']))); if(!$ids)return []; $args['include']=$ids; $args['orderby']='include'; }elseif($d['source']==='featured'){ $args['featured']=true; $args['orderby']=$d['orderby']; $args['order']=$d['order']; if($d['orderby']==='price')$args['orderby']='price'; }else{ $args['orderby']='date'; $args['order']='DESC'; }
return wc_get_products($args); }
/* فیلد اختصاصی متن محصول ناموجود */ function bluprint_product_out_of_stock_field(){ woocommerce_wp_text_input([ 'id'=>'_bluprint_out_of_stock_text', 'label'=>'متن جایگزین وضعیت ناموجود', 'desc_tip'=>true, 'description'=>'در صورت ناموجود بودن محصول، این متن به‌جای دکمه خرید نمایش داده می‌شود. در صورت خالی بودن، متن پیش‌فرض سکشن محصولات استفاده خواهد شد.', 'type'=>'text' ]); }
add_action('woocommerce_product_options_inventory_product_data','bluprint_product_out_of_stock_field'); function bluprint_save_product_out_of_stock_field($post_id){ if(!isset($_POST['_bluprint_out_of_stock_text']))return; $text=sanitize_text_field(wp_unslash($_POST['_bluprint_out_of_stock_text'])); if($text===''){ delete_post_meta($post_id,'_bluprint_out_of_stock_text'); }else{ update_post_meta($post_id,'_bluprint_out_of_stock_text',$text); }
} add_action('woocommerce_process_product_meta','bluprint_save_product_out_of_stock_field');